import type { MetadataRoute } from "next";

/**
 * PWA manifest.
 *
 * Icons are generated by `scripts/generate-icons.mjs` (no image dependencies):
 * the APON mark as a rounded 192/512 pair plus a padded maskable variant, which Android needs so
 * the mark survives its circular/rounded masks.
 */
export default function manifest(): MetadataRoute.Manifest {
  return {
    name: "APON — Everyone belongs",
    short_name: "APON",
    description:
      "Small weekly circles of 4–6 people near you, anywhere in Bangladesh — because everyone belongs.",
    start_url: "/",
    scope: "/",
    display: "standalone",
    orientation: "portrait",
    background_color: "#f5f7f7",
    theme_color: "#0f766e",
    categories: ["social", "lifestyle"],
    icons: [
      { src: "/icons/icon-192.png", sizes: "192x192", type: "image/png", purpose: "any" },
      { src: "/icons/icon-512.png", sizes: "512x512", type: "image/png", purpose: "any" },
      {
        src: "/icons/maskable-512.png",
        sizes: "512x512",
        type: "image/png",
        purpose: "maskable",
      },
    ],
  };
}
